answer=""
read answer </dev/tty 2>/dev/null || answer=""
printf '─────────────────────────────\n' >/dev/tty 2>&1

case "$answer" in
	[Nn]*)
		printf 'v1 declined %s\n' "$now" >"$state_file" 2>/dev/null || true
