// same path that bare `entire` runs in an unconfigured repo — and does NOT
// modify the existing `entire enable` command. After a successful setup it
// records onboarding state so the one-time teammate nudge never fires here
// again.
func newDevSetupCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "setup",
		Short: "Set up Entire for yourself in this repository",
		Long: `Set up Entire for yourself in the current repository.

This is a developer-level action (separate from repository-level 'entire adopt').
It configures your local git hooks and local Entire integration for this clone.
It does not commit anything.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			if _, err := paths.WorktreeRoot(ctx); err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run 'entire setup' from within a git repository.")
				return NewSilentError(errors.New("not a git repository"))
			}

			if err := runSetupFlow(ctx, cmd.OutOrStdout(), EnableOptions{}); err != nil {
				return err
			}

			// Record that this developer completed onboarding in this clone, so
			// the one-time nudge never re-fires here. Best-effort: never fail
			// setup because the marker could not be written.
			_ = onboarding.WriteStatus(ctx, onboarding.StatusAccepted)
			return nil
		},
	}
}

