package cli

import (
	"context"
	"fmt"
	"io"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/onboarding"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/spf13/cobra"
)

// onboardingNudgeSkip lists command names for which the post-run onboarding
// nudge must never fire — lifecycle/auth commands where an unrelated "set up
// Entire?" prompt would be confusing or redundant. The bare root command
// ("entire") is also skipped because it runs the setup flow itself.
var onboardingNudgeSkip = map[string]bool{
	"entire":    true, // root command (already drives setup when unconfigured)
	"setup":     true,
	"enable":    true,
	"disable":   true,
	"adopt":     true,
	"onboard":   true,
	"configure": true,
	"clean":     true,
	"reset":     true,
	"login":     true,
	"logout":    true,
	"version":   true,
	"help":      true,
}

// newOnboardCmd registers the hidden `entire onboard --check`. It is invoked by
// the committed .githooks/ scripts (and is safe to run by hand). Without
// --check it just prints help.
func newOnboardCmd() *cobra.Command {
	var check bool
	cmd := &cobra.Command{
		Use:    "onboard",
		Short:  "One-time Entire onboarding check (internal)",
		Hidden: true,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if !check {
				return cmd.Help()
			}
			runOnboardingCheck(cmd)
			return nil
		},
	}
	cmd.Flags().BoolVar(&check, "check", false, "Run the one-time onboarding check used by git hooks")
	return cmd
}

// maybePromptOnboarding is the gated nudge wired into the root
// PersistentPostRun. It runs after a successful, non-hidden command and is a
// near-instant no-op unless every condition for a one-time prompt is met. It
// never returns an error and never disrupts the command the user actually ran.
func maybePromptOnboarding(cmd *cobra.Command) {
	if cmd == nil || onboardingNudgeSkip[cmd.Name()] {
		return
	}
	runOnboardingCheck(cmd)
}

// runOnboardingCheck performs the one-time, consent-based teammate prompt. It is
// shared by `entire onboard --check` and the post-run nudge. Each guard is
// cheap and ordered so the common case (not an adopted repo, or already
// answered) exits with a single stat.
func runOnboardingCheck(cmd *cobra.Command) {
	ctx := cmd.Context()

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return // not in a git repo
	}
	if !onboarding.RepoIsAdopted(repoRoot) {
		return // repo has not been adopted by the team
	}
	if settings.IsSetUpAny(ctx) {
		return // this developer is already set up here
	}

	status, _ := onboarding.ReadStatus(ctx)
	if onboarding.Answered(status) {
		return // already accepted or declined in this clone
	}

	if !interactive.CanPromptInteractively() {
		// Can't ask right now (CI, piped, agent subprocess). Record a
		// non-final "deferred" marker only if we've never recorded anything,
		// so a real terminal can still ask later.
		if status == onboarding.StatusUnseen {
			_ = onboarding.WriteStatus(ctx, onboarding.StatusDeferred)
		}
		return
	}

	out := cmd.OutOrStdout()
	slug := onboarding.RepoSlug(ctx, repoRoot)
	printOnboardingBanner(out, slug)

	confirmed := true
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Set up Entire?").
				Affirmative("Yes").
				Negative("No").
				Value(&confirmed),
		),
	)
	if err := form.Run(); err != nil {
		// Treat cancellation/abort as "ask me later": leave state unset so the
		// developer is not silently opted out by hitting Ctrl+C.
		return
	}

	if !confirmed {
		_ = onboarding.WriteStatus(ctx, onboarding.StatusDeclined)
		fmt.Fprintln(out, "No problem — you won't be asked again. Run 'entire setup' anytime.")
		return
	}

	if err := runSetupFlow(ctx, out, EnableOptions{}); err != nil {
		// Setup failed; don't burn the prompt — let them try again next time.
		fmt.Fprintf(cmd.ErrOrStderr(), "Entire setup did not complete: %v\n", err)
		return
	}
	_ = onboarding.WriteStatus(ctx, onboarding.StatusAccepted)
}

// printOnboardingBanner renders the bordered teammate-facing introduction.
func printOnboardingBanner(w io.Writer, slug string) {
	const rule = "─────────────────────────────"
	fmt.Fprintf(w, "\n%s\n", rule)
	if slug != "" && slug != "this repository" {
		fmt.Fprintf(w, "%s uses Entire.\n\n", slug)
	} else {
		fmt.Fprintln(w, "This repository uses Entire.\n")
	}
	fmt.Fprintln(w, "Entire automatically captures coding progress and creates checkpoints")
	fmt.Fprintln(w, "so teammates can see work as it evolves.")
	fmt.Fprintf(w, "\nLearn more:\n%s\n", onboarding.DefaultDocsURL)
	fmt.Fprintf(w, "%s\n", rule)
}

// compile-time assertion that context is used (keeps import if refactored).
var _ = context.Background

