package cli

import (
	"fmt"
	"io"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/onboarding"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/spf13/cobra"
)

// onboardingNudgeSkip lists command names for which the post-run onboarding
// nudge must never fire — lifecycle/auth commands where an unrelated "set up
// Entire?" prompt would be confusing or redundant. The bare root command
// ("entire") is also skipped because it runs the setup flow itself.
var onboardingNudgeSkip = map[string]bool{
	"entire":    true, // root command (already drives setup when unconfigured)
	"enable":    true,
	"disable":   true,
	"adopt":     true,
	"onboard":   true,
	"configure": true,
	"clean":     true,
	"reset":     true,
	"login":     true,
	"logout":    true,
	"version":   true,
	"help":      true,
}

// newOnboardCmd registers the hidden `entire onboard --check`. It is invoked by
// the committed .githooks/ scripts (and is safe to run by hand). Without
// --check it just prints help.
func newOnboardCmd() *cobra.Command {
	var check bool
	cmd := &cobra.Command{
		Use:    "onboard",
		Short:  "One-time Entire onboarding check (internal)",
		Hidden: true,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if !check {
				return cmd.Help()
			}
			runOnboardingCheck(cmd)
			return nil
		},
	}
	cmd.Flags().BoolVar(&check, "check", false, "Run the one-time onboarding check used by git hooks")
	return cmd
}

// maybePromptOnboarding is the gated nudge wired into the root
// PersistentPostRun. It runs after a successful, non-hidden command and is a
// near-instant no-op unless every condition for a one-time prompt is met. It
// never returns an error and never disrupts the command the user actually ran.
func maybePromptOnboarding(cmd *cobra.Command) {
	if cmd == nil || onboardingNudgeSkip[cmd.Name()] {
		return
	}
	runOnboardingCheck(cmd)
}

// runOnboardingCheck performs the one-time, consent-based teammate prompt. It is
// shared by `entire onboard --check` and the post-run nudge. Each guard is
// cheap and ordered so the common case (not an adopted repo, or already
// answered) exits with a single stat.
func runOnboardingCheck(cmd *cobra.Command) {
	ctx := cmd.Context()

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return // not in a git repo
	}
	if !onboarding.RepoIsAdopted(repoRoot) {
		return // repo has not been adopted by the team
	}
	if settings.IsSetUpAny(ctx) {
		return // this developer is already set up here
	}

	status, _ := onboarding.ReadStatus(ctx)
	if onboarding.Answered(status) {
		return // already accepted or declined in this clone
	}

	if !interactive.CanPromptInteractively() {
		// Can't ask right now (CI, piped, agent subprocess). Record a
		// non-final "deferred" marker only if we've never recorded anything,
		// so a real terminal can still ask later.
		if status == onboarding.StatusUnseen {
			_ = onboarding.WriteStatus(ctx, onboarding.StatusDeferred)
		}
		return
	}

	out := cmd.OutOrStdout()
	slug := onboarding.RepoSlug(ctx, repoRoot)
	printOnboardingBanner(out, slug)

	confirmed := true
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Set up Entire?").
				Affirmative("Yes").
				Negative("No").
				Value(&confirmed),
		),
	)
	if err := form.Run(); err != nil {
		// Treat cancellation/abort as "ask me later": leave state unset so the
		// developer is not silently opted out by hitting Ctrl+C.
		return
	}

	if !confirmed {
		_ = onboarding.WriteStatus(ctx, onboarding.StatusDeclined)
		fmt.Fprintln(out, "No problem — you won't be asked again. Run 'entire setup' anytime.")
		return
	}

	if err := runSetupFlow(ctx, out, EnableOptions{}); err != nil {
		// Setup failed; don't burn the prompt — let them try again next time.
		fmt.Fprintf(cmd.ErrOrStderr(), "Entire setup did not complete: %v\n", err)
		return
	}
	_ = onboarding.WriteStatus(ctx, onboarding.StatusAccepted)
}

// printOnboardingBanner renders the bordered teammate-facing introduction.
func printOnboardingBanner(w io.Writer, slug string) {
	const rule = "─────────────────────────────"
	fmt.Fprintf(w, "\n%s\n", rule)
	if slug != "" && slug != "this repository" {
		fmt.Fprintf(w, "%s uses Entire.\n\n", slug)
	} else {
		fmt.Fprintf(w, "This repository uses Entire.\n\n")
	}
	fmt.Fprintln(w, "Entire automatically captures coding progress and creates checkpoints")
	fmt.Fprintln(w, "so teammates can see work as it evolves.")
	fmt.Fprintf(w, "\nLearn more:\n%s\n", onboarding.DefaultDocsURL)
	fmt.Fprintf(w, "%s\n", rule)
}

package cli

import (
	"context"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/onboarding"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/spf13/cobra"
)

func TestRunAdopt_CreatesCommittedArtifacts(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)

	written, err := runAdopt(context.Background(), dir)
	if err != nil {
		t.Fatalf("runAdopt: %v", err)
	}

	wantFiles := []string{
		".entire/config",
		".githooks/" + onboardingShellName,
		".githooks/post-checkout",
		".githooks/post-merge",
		"README.md",
	}
	for _, rel := range wantFiles {
		if _, statErr := os.Stat(filepath.Join(dir, rel)); statErr != nil {
			t.Errorf("expected %s to exist: %v", rel, statErr)
		}
	}
	if len(written) != len(wantFiles) {
		t.Errorf("runAdopt reported %d files, want %d (%v)", len(written), len(wantFiles), written)
	}

	if !onboarding.RepoIsAdopted(dir) {
		t.Fatal("repo should be adopted after runAdopt")
	}
	cfg, err := onboarding.ReadConfig(dir)
	if err != nil || !cfg.Adopted {
		t.Fatalf("ReadConfig adopted = %+v, %v", cfg, err)
	}

	// Hooks must be executable so they actually run as git hooks.
	for _, name := range append([]string{onboardingShellName}, committedHookWrappers...) {
		info, statErr := os.Stat(filepath.Join(dir, ".githooks", name))
		if statErr != nil {
			t.Fatalf("stat hook %s: %v", name, statErr)
		}
		if info.Mode()&0o100 == 0 {
			t.Errorf("hook %s is not executable (mode %v)", name, info.Mode())
		}
	}

	// README carries the cross-platform install path for teammates with no CLI.
	readme := readFile(t, filepath.Join(dir, "README.md"))
	for _, want := range []string{readmeStartMarker, readmeEndMarker, "install.sh | bash", "entire setup"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README missing %q", want)
		}
	}
}

func TestUpdateReadme_Idempotent(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()

	if _, err := updateReadme(dir); err != nil {
		t.Fatalf("updateReadme #1: %v", err)
	}
	if _, err := updateReadme(dir); err != nil {
		t.Fatalf("updateReadme #2: %v", err)
	}

	readme := readFile(t, filepath.Join(dir, "README.md"))
	if n := strings.Count(readme, readmeStartMarker); n != 1 {
		t.Fatalf("expected exactly 1 start marker, got %d", n)
	}
	if n := strings.Count(readme, readmeEndMarker); n != 1 {
		t.Fatalf("expected exactly 1 end marker, got %d", n)
	}
}

func TestUpdateReadme_PreservesExistingContent(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	original := "# My Project\n\nSome important docs.\n"
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte(original), 0o644); err != nil {
		t.Fatal(err)
	}

	if _, err := updateReadme(dir); err != nil {
		t.Fatalf("updateReadme: %v", err)
	}

	readme := readFile(t, filepath.Join(dir, "README.md"))
	if !strings.Contains(readme, "# My Project") || !strings.Contains(readme, "Some important docs.") {
		t.Fatal("updateReadme dropped existing README content")
	}
	if !strings.Contains(readme, readmeStartMarker) {
		t.Fatal("updateReadme did not add the Entire section")
	}
}

func TestReplaceBetween(t *testing.T) {
	t.Parallel()
	got := replaceBetween("a START old END b", "START", "END", "START new END")
	if want := "a START new END b"; got != want {
		t.Fatalf("replaceBetween = %q, want %q", got, want)
	}
}

func readFile(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return string(data)
}

// newOnboardTestCmd builds a minimal cobra command with a discardable output
// and a real context for exercising the nudge logic.
func newOnboardTestCmd(name string) *cobra.Command {
	c := &cobra.Command{Use: name}
	c.SetContext(context.Background())
	c.SetOut(io.Discard)
	c.SetErr(io.Discard)
	return c
}

func TestRunOnboardingCheck_DeferredWhenNonInteractive(t *testing.T) {
	// Uses CWD-based git/settings resolution; not parallel.
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	// Adopted, but this developer is not set up here.
	mustWriteConfig(t, dir)

	runOnboardingCheck(newOnboardTestCmd("status"))

	if s, _ := onboarding.ReadStatus(context.Background()); s != onboarding.StatusDeferred {
		t.Fatalf("status = %q, want deferred (non-interactive should defer)", s)
	}
}

func TestRunOnboardingCheck_NoopWhenNotAdopted(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)

	runOnboardingCheck(newOnboardTestCmd("status"))

	if s, _ := onboarding.ReadStatus(context.Background()); s != onboarding.StatusUnseen {
		t.Fatalf("status = %q, want unseen (non-adopted repo must be a no-op)", s)
	}
}

func TestRunOnboardingCheck_NoopWhenAlreadyAnswered(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	mustWriteConfig(t, dir)
	if err := onboarding.WriteStatus(context.Background(), onboarding.StatusDeclined); err != nil {
		t.Fatal(err)
	}

	runOnboardingCheck(newOnboardTestCmd("status"))

	if s, _ := onboarding.ReadStatus(context.Background()); s != onboarding.StatusDeclined {
		t.Fatalf("status = %q, want declined unchanged", s)
	}
}

func REDACTED(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	mustWriteConfig(t, dir)

	// A skip-listed command must not even record a deferred marker.
	maybePromptOnboarding(newOnboardTestCmd("login"))
	if s, _ := onboarding.ReadStatus(context.Background()); s != onboarding.StatusUnseen {
		t.Fatalf("status = %q after skip-listed command, want unseen", s)
	}

	// A non-skip-listed command goes through the gate (defers, non-interactive).
	maybePromptOnboarding(newOnboardTestCmd("status"))
	if s, _ := onboarding.ReadStatus(context.Background()); s != onboarding.StatusDeferred {
		t.Fatalf("status = %q after normal command, want deferred", s)
	}
}

func mustWriteConfig(t *testing.T, dir string) {
	t.Helper()
	if err := onboarding.WriteConfig(dir, &onboarding.Config{Adopted: true, DocsURL: onboarding.DefaultDocsURL}); err != nil {
		t.Fatal(err)
	}
}

