1	// Package onboarding implements the lightweight, consent-based team-adoption
2	// flow for the Entire CLI.
3	//
4	// Two concepts are kept strictly separate:
5	//
6	//   - Repository adoption ("entire adopt") writes committed artifacts that
7	//     advertise that a repo uses Entire: the .entire/config marker, committed
8	//     .githooks/ scripts, and a README section. This package owns reading and
9	//     writing the .entire/config marker.
10	//
11	//   - Per-developer onboarding state ("have we already asked this person?") is
12	//     stored OUTSIDE the work tree, under <git-common-dir>/entire/prompt-seen,
13	//     so it is never committed, survives future pulls, and is unique per clone.
14	//
15	// This package is intentionally UI-free and dependency-light (stdlib + git via
16	// exec only) so it can be imported anywhere in the CLI without import cycles.
17	// All interactive prompting lives in the cli package.
18	package onboarding
19	
20	import (
21		"context"
22		"encoding/json"
23		"fmt"
24		"os"
25		"os/exec"
26		"path/filepath"
27		"strings"
28		"time"
29	)
30	
31	// ConfigRelPath is the committed adoption marker, relative to the work-tree
32	// root. Its presence is what makes a repository "adopted".
33	const ConfigRelPath = ".entire/config"
34	
35	// DefaultDocsURL is the learn-more link shown to teammates during onboarding.
36	const DefaultDocsURL = "https://docs.entire.io/overview"
37	
38	// Status records whether the current developer has already been asked, in this
39	// clone, whether they want to onboard. It is persisted as the first token of
40	// the prompt-seen file (format: "v1 <status> <rfc3339>").
41	type Status string
42	
43	const (
44		// StatusUnseen means the developer has never been asked in this clone.
45		StatusUnseen Status = ""
46		// StatusAccepted means the developer accepted and was set up.
47		StatusAccepted Status = "accepted"
48		// StatusDeclined means the developer declined; never ask again.
49		StatusDeclined Status = "declined"
50		// StatusDeferred means we could not ask (non-interactive context). We are
51		// allowed to ask again later in an interactive session.
52		StatusDeferred Status = "deferred"
53	)
54	
55	// stateVersion lets us deliberately re-ask on a future major onboarding change
56	// without re-asking people who already answered the current version.
57	const stateVersion = "v1"
58	
59	// Config is the committed .entire/config adoption marker. It is intentionally
60	// small, human-readable, and language-agnostic — it touches no build system.
61	type Config struct {
62		Adopted    bool   `json:"adopted"`
63		Repo       string `json:"repo,omitempty"`
64		DocsURL    string `json:"docs_url,omitempty"`
65		MinVersion string `json:"min_version,omitempty"`
66		AdoptedAt  string `json:"adopted_at,omitempty"`
67	}
68	
69	// ConfigPath returns the absolute path to the adoption marker for the given
70	// work-tree root.
71	func ConfigPath(repoRoot string) string {
72		return filepath.Join(repoRoot, ConfigRelPath)
73	}
74	
75	// RepoIsAdopted reports whether the work tree at repoRoot contains a committed
76	// adoption marker. It is deliberately a cheap stat so it is safe to call on a
77	// hot path (e.g. the root PersistentPostRun nudge).
78	func RepoIsAdopted(repoRoot string) bool {
79		if repoRoot == "" {
80			return false
81		}
82		info, err := os.Stat(ConfigPath(repoRoot))
83		return err == nil && !info.IsDir()
84	}
85	
86	// ReadConfig loads the adoption marker. A missing file is reported via
87	// os.IsNotExist on the returned error.
88	func ReadConfig(repoRoot string) (*Config, error) {
89		data, err := os.ReadFile(ConfigPath(repoRoot))
90		if err != nil {
91			return nil, err
92		}
93		var cfg Config
94		if err := json.Unmarshal(data, &cfg); err != nil {
95			return nil, fmt.Errorf("parse %s: %w", ConfigRelPath, err)
96		}
97		return &cfg, nil
98	}
99	
100	// WriteConfig writes the adoption marker, creating the .entire/ directory if
101	// needed. The file is pretty-printed JSON so it reviews cleanly in a PR.
102	func WriteConfig(repoRoot string, cfg *Config) error {
103		dir := filepath.Dir(ConfigPath(repoRoot))
104		if err := os.MkdirAll(dir, 0o755); err != nil {
105			return fmt.Errorf("create %s: %w", dir, err)
106		}
107		data, err := json.MarshalIndent(cfg, "", "  ")
108		if err != nil {
109			return fmt.Errorf("encode adoption config: %w", err)
110		}
111		data = append(data, '\n')
112		if err := os.WriteFile(ConfigPath(repoRoot), data, 0o644); err != nil {
113			return fmt.Errorf("write %s: %w", ConfigRelPath, err)
114		}
115		return nil
116	}
117	
118	// promptSeenPath returns <git-common-dir>/entire/prompt-seen. The git common
119	// dir is used (not the work-tree .git) so the answer is shared across linked
120	// worktrees of the same clone but never committed.
121	func promptSeenPath(ctx context.Context) (string, error) {
122		common, err := gitCommonDir(ctx)
123		if err != nil {
124			return "", err
125		}
126		return filepath.Join(common, "entire", "prompt-seen"), nil
127	}
128	
129	// ReadStatus returns the developer's onboarding answer for this clone, or
130	// StatusUnseen if they have not been asked yet.
131	func ReadStatus(ctx context.Context) (Status, error) {
132		path, err := promptSeenPath(ctx)
133		if err != nil {
134			return StatusUnseen, err
135		}
136		data, err := os.ReadFile(path)
137		if err != nil {
138			if os.IsNotExist(err) {
139				return StatusUnseen, nil
140			}
141			return StatusUnseen, err
142		}
143		fields := strings.Fields(string(data))
144		// Format: "v1 <status> <rfc3339>". Be lenient about extra/missing trailing
145		// fields so a hand-edited or future-format file never crashes a git command.
146		if len(fields) >= 2 {
147			return Status(fields[1]), nil
148		}
149		if len(fields) == 1 {
150			// Tolerate a bare status token written by the shell hook fallback.
151			return Status(fields[0]), nil
152		}
153		return StatusUnseen, nil
154	}
155	
156	// WriteStatus records the developer's onboarding answer for this clone.
157	func WriteStatus(ctx context.Context, s Status) error {
158		path, err := promptSeenPath(ctx)
159		if err != nil {
160			return err
161		}
162		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
163			return fmt.Errorf("create onboarding state dir: %w", err)
164		}
165		line := fmt.Sprintf("%s %s %s\n", stateVersion, s, time.Now().UTC().Format(time.RFC3339))
166		if err := os.WriteFile(path, []byte(line), 0o644); err != nil {
167			return fmt.Errorf("write onboarding state: %w", err)
168		}
169		return nil
170	}
171	
172	// Answered reports whether the developer has given a final answer (accepted or
173	// declined) in this clone. A deferred state is not final — we may ask again.
174	func Answered(s Status) bool {
175		return s == StatusAccepted || s == StatusDeclined
176	}
177	
178	// adoptAskedPath returns <git-common-dir>/entire/adopt-asked: the marker that
179	// records we already asked this developer (the repo champion) whether to adopt
180	// Entire for the whole team. Kept separate from prompt-seen so the champion and
181	// teammate prompts never collide.
182	func adoptAskedPath(ctx context.Context) (string, error) {
183		common, err := gitCommonDir(ctx)
184		if err != nil {
185			return "", err
186		}
187		return filepath.Join(common, "entire", "adopt-asked"), nil
188	}
189	
190	// AdoptAsked reports whether the champion has already been asked, in this clone,
191	// to adopt Entire for the team.
192	func AdoptAsked(ctx context.Context) (bool, error) {
193		path, err := adoptAskedPath(ctx)
194		if err != nil {
195			return false, err
196		}
197		_, err = os.Stat(path)
198		if err == nil {
199			return true, nil
200		}
201		if os.IsNotExist(err) {
202			return false, nil
203		}
204		return false, err
205	}
206	
207	// MarkAdoptAsked records that the champion has been asked (so we never nag).
208	func MarkAdoptAsked(ctx context.Context) error {
209		path, err := adoptAskedPath(ctx)
210		if err != nil {
211			return err
212		}
213		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
214			return fmt.Errorf("create onboarding state dir: %w", err)
215		}

