	}

	if err := WriteStatus(ctx, StatusAccepted); err != nil {
		t.Fatalf("WriteStatus: %v", err)
	}
	if s, err := ReadStatus(ctx); err != nil || s != StatusAccepted {
		t.Fatalf("ReadStatus after write = %q, %v; want accepted, nil", s, err)
	}

