// and a real context for exercising the nudge logic.
func newOnboardTestCmd(name string) *cobra.Command {
	c := &cobra.Command{Use: name}
	c.SetContext(context.Background())
	c.SetOut(io.Discard)
	c.SetErr(io.Discard)
	return c
}

