	cmd := &cobra.Command{
		Use:    "onboard",
		Short:  "One-time Entire onboarding check (internal)",
		Hidden: true,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if !check {
				return cmd.Help()
			}
			runTeammateOnboarding(cmd)
			return nil
		},
	}
